import type { FormatFn } from "style-dictionary/types";

type Entry = { path: string[]; value: string };

type Model = {
  /** Semantic colors per theme, with the `theme.<mode>` prefix removed (path starts at `color`). */
  themes: { dark: Entry[]; light: Entry[] };
  /** Everything that is not themed and not palette: spacing, radius, typography, elevation. */
  scales: Entry[];
};

const HEADER =
  "Do not edit directly, this file is generated by scripts/build-tokens.ts.";

const varName = (path: string[]): string => {
  return `--ds-${path.join("-")}`;
};

const sameKeys = (a: Entry[], b: Entry[]): boolean => {
  const keys = (entries: Entry[]) =>
    entries.map((entry) => entry.path.join(".")).sort();
  return JSON.stringify(keys(a)) === JSON.stringify(keys(b));
};

/**
 * Splits the resolved dictionary into themed colors and scales. The palette layer is dropped
 * here on purpose: it is the only place raw values live and it must never reach the outputs.
 */
export const toModel = (
  tokens: ReadonlyArray<{ path: string[]; $value?: unknown }>,
): Model => {
  const model: Model = { themes: { dark: [], light: [] }, scales: [] };

  for (const token of tokens) {
    const [root, mode, ...rest] = token.path;
    if (root === "palette") continue;
    if (typeof token.$value !== "string" && typeof token.$value !== "number") {
      throw new Error(`Token ${token.path.join(".")} has no primitive $value`);
    }
    const value = String(token.$value);

    if (root === "theme") {
      if (mode !== "dark" && mode !== "light") {
        throw new Error(
          `Unknown theme "${String(mode)}" in ${token.path.join(".")}`,
        );
      }
      model.themes[mode].push({ path: rest, value });
    } else {
      model.scales.push({ path: token.path, value });
    }
  }

  if (!sameKeys(model.themes.dark, model.themes.light)) {
    throw new Error(
      "Light and dark themes must define exactly the same semantic tokens",
    );
  }
  return model;
};

const declarations = (entries: Entry[]): string => {
  return entries
    .map(({ path, value }) => `  ${varName(path)}: ${value};`)
    .join("\n");
};

/** CSS custom properties. Dark is the default; `data-theme="light"` switches it. */
export const cssFormat: FormatFn = ({ dictionary }) => {
  const { themes, scales } = toModel(dictionary.allTokens);
  return [
    `/* ${HEADER} */`,
    `:root {\n${declarations(scales)}\n}`,
    `:root,\n[data-theme="dark"] {\n  color-scheme: dark;\n${declarations(themes.dark)}\n}`,
    `[data-theme="light"] {\n  color-scheme: light;\n${declarations(themes.light)}\n}`,
    "",
  ].join("\n\n");
};

/** Tailwind v4 theme: maps Tailwind namespaces onto the CSS variables above. */
export const tailwindFormat: FormatFn = ({ dictionary }) => {
  const { themes, scales } = toModel(dictionary.allTokens);
  // Only the declared steps exist: `p-7` or `w-11` generate no style at all, instead of being
  // multiplied from a base. The reset also clears Tailwind's bare `--spacing`.
  const lines: string[] = ["  --color-*: initial;", "  --spacing-*: initial;"];
  const map = (name: string, path: string[]) =>
    lines.push(`  ${name}: var(${varName(path)});`);

  for (const { path } of themes.dark)
    map(`--color-${path.slice(1).join("-")}`, path);

  for (const { path } of scales) {
    const [group, name] = path;
    if (group === undefined || name === undefined) continue;
    if (group === "space") map(`--spacing-${name}`, path);
    else if (group === "radius") {
      if (name !== "base") map(`--radius-${name}`, path);
    } else if (group === "font") map(`--font-${name}`, path);
    else if (group === "text") {
      const [size, suffix] = name.split("-line-height");
      map(
        suffix === undefined ? `--text-${size}` : `--text-${size}--line-height`,
        path,
      );
    } else if (group === "font-weight") map(`--font-weight-${name}`, path);
    else if (group === "leading") map(`--leading-${name}`, path);
    else if (group === "shadow") map(`--shadow-${name}`, path);
  }

  return `/* ${HEADER} */\n\n@theme inline {\n${lines.join("\n")}\n}\n`;
};

type Tree = { [key: string]: Tree | string };

const toTree = (entries: Entry[]): Tree => {
  const root: Tree = {};
  for (const { path } of entries) {
    let node = root;
    path.forEach((key, index) => {
      if (index === path.length - 1) {
        node[key] = `var(${varName(path)})`;
        return;
      }
      const next = node[key];
      if (typeof next === "string")
        throw new Error(`Token ${path.join(".")} collides with a leaf`);
      node = node[key] = next ?? {};
    });
  }
  return root;
};

type ValueTree = { [key: string]: ValueTree | string };

const toValueTree = (entries: Entry[]): ValueTree => {
  const root: ValueTree = {};
  for (const { path, value } of entries) {
    let node = root;
    path.forEach((key, index) => {
      if (index === path.length - 1) {
        node[key] = value;
        return;
      }
      const next = node[key];
      if (typeof next === "string")
        throw new Error(`Token ${path.join(".")} collides with a leaf`);
      node = node[key] = next ?? {};
    });
  }
  return root;
};

/** Typed module: token names (a typo is a compile error) and the resolved per-theme values. */
export const tsFormat: FormatFn = ({ dictionary }) => {
  const { themes, scales } = toModel(dictionary.allTokens);
  const flat = (entries: Entry[]) =>
    Object.fromEntries(
      entries.map(({ path, value }) => [path.slice(1).join("."), value]),
    );

  return [
    `// ${HEADER}`,
    "",
    "/** Every theme, in the order they are declared. Dark is the default. */",
    `export const themes = ["dark", "light"] as const;`,
    "",
    "export type Theme = (typeof themes)[number];",
    "",
    "/** Resolved OKLCH value of every semantic color, per theme. */",
    `export const themeValues = ${JSON.stringify({ dark: flat(themes.dark), light: flat(themes.light) }, null, 2)} as const;`,
    "",
    "/** Dotted name of a semantic color, for example `bg.base` or `text.on-primary`. */",
    `export type ColorToken = keyof (typeof themeValues)["dark"];`,
    "",
    "/** Resolved value of every scale token (space, radius, font, text, shadow...), for documentation. */",
    `export const scaleValues = ${JSON.stringify(toValueTree(scales), null, 2)} as const;`,
    "",
    "/** `var(--ds-...)` references. Use these, never raw values. */",
    `export const tokens = ${JSON.stringify(toTree([...themes.dark, ...scales]), null, 2)} as const;`,
    "",
  ].join("\n");
};
